<script setup lang="ts">
import { computed, onMounted, ref, toRaw } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { CircleDot, ListChecks, TextCursorInput, CircleCheck, FileText, Layers3, List, Plus, ArrowLeft, ArrowUp, ArrowDown, Copy, Pencil, Power, Trash2, GripVertical, Check, Smartphone, Settings2, Search } from 'lucide-vue-next'
import { request, send } from './api'
import { fieldNames, flattenFields, isAnswer, newField, initialValues, type FieldKind, type TypeRecord, type QuestionField } from '../../shared/question-types'
import QuestionFields from './QuestionFields.vue'
import QuestionPreview from './QuestionPreview.vue'
const props=defineProps<{exams:any[]}>()
const records=ref<TypeRecord[]>([]),loading=ref(false),error=ref(''),search=ref(''),status=ref('all')
const draft=ref<TypeRecord|null>(null),selected=ref(''),tab=ref('design'),saving=ref(false),saveError=ref(''),baseline=ref('')
const sample=ref<Record<string,any>>({}),answers=ref<Record<string,any>>({}),previewMode=ref('mobile'),ruleExam=ref('')
const icons={material:FileText,options:List,single:CircleDot,multiple:ListChecks,boolean:CircleCheck,text:TextCursorInput,group:Layers3}
const componentKinds=Object.keys(fieldNames) as FieldKind[]
const descriptions:Record<FieldKind,string>={material:'案例、阅读材料与背景',options:'多个小题复用一组选项',single:'多个选项，选择一个',multiple:'多个选项，选择多个',boolean:'正确 / 错误',text:'文字作答，自评或 AI 判分',group:'组合多个独立的小题'}
const filtered=computed(()=>records.value.filter(t=>t.name.includes(search.value)&&(status.value==='all'||t.enabled===(status.value==='enabled'))))
const allFields=computed(()=>flattenFields(draft.value?.definition.fields||[]))
const active=computed(()=>allFields.value.find(f=>f.id===selected.value))
const entries=computed(()=>{const result:{f:QuestionField;list:QuestionField[];depth:number}[]=[];const walk=(list:QuestionField[],depth=0)=>list.forEach(f=>{result.push({f,list,depth});walk(f.children,depth+1)});walk(draft.value?.definition.fields||[]);return result})
const dirty=computed(()=>draft.value&&JSON.stringify(draft.value)!==baseline.value)
async function load(){loading.value=true;error.value='';try{records.value=await request('/admin/question-types')}catch(e:any){error.value=e.message}finally{loading.value=false}}
function open(record?:TypeRecord,copy=false){
  draft.value=record?structuredClone(toRaw(record)):{id:'type-'+crypto.randomUUID(),name:'',description:'',enabled:true,builtin:false,version:1,definition:{fields:[newField('single','response')],examRules:{}}}
  if(copy){draft.value.id='type-'+crypto.randomUUID();draft.value.name+='（副本）';draft.value.version=1;draft.value.builtin=false;draft.value.question_count=0}
  if(!record||copy)(draft.value as any).isNew=true
  selected.value=draft.value.definition.fields[0]?.id||'';tab.value='design';saveError.value='';ruleExam.value='';sample.value=initialValues(draft.value.definition);answers.value={};baseline.value=JSON.stringify(draft.value)
}
async function back(){if(dirty.value){try{await ElMessageBox.confirm('尚未保存的题型修改将被放弃。','返回题型列表',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑',type:'warning'})}catch{return}}draft.value=null}
async function save(){
  if(!draft.value||saving.value)return;saving.value=true;saveError.value=''
  try{const d=draft.value;const result=await send('/admin/question-types/'+d.id,{name:d.name,description:d.description,definition:d.definition,version:(d as any).isNew?undefined:d.version},'PUT');draft.value=result;baseline.value=JSON.stringify(result);ElMessage.success('题型已保存，已有题目保持原版本');await load()}catch(e:any){saveError.value=e.message}finally{saving.value=false}
}
function add(kind:FieldKind){if(!draft.value)return;const f=newField(kind,'f'+crypto.randomUUID().replaceAll('-',''));const parent=active.value?.kind==='group'?active.value.children:draft.value.definition.fields;parent.push(f);selected.value=f.id;sample.value={...initialValues(draft.value.definition),...sample.value}}
function move(f:QuestionField,list:QuestionField[],direction:number){const index=list.indexOf(f),next=index+direction;if(next<0||next>=list.length)return;list.splice(index,1);list.splice(next,0,f)}
async function remove(f:QuestionField,list:QuestionField[]){
  const ids=new Set(flattenFields([f]).map(x=>x.id));if(allFields.value.some(x=>!ids.has(x.id)&&ids.has(x.optionsSource)))return ElMessage.warning('该共用选项仍被使用，请先修改小题的选项来源')
  list.splice(list.indexOf(f),1);for(const rules of Object.values(draft.value!.definition.examRules))for(const key of ids)delete rules[key];selected.value=draft.value!.definition.fields[0]?.id||''
}
async function toggle(t:TypeRecord){try{await ElMessageBox.confirm(t.enabled?'停用后无法用于新增题目，已有题目仍可正常使用。':'启用后可用于新增题目。',t.enabled?'停用题型':'启用题型',{confirmButtonText:'确定',cancelButtonText:'取消'});await send('/admin/question-types/'+t.id,{enabled:!t.enabled},'PATCH');await load()}catch(e:any){if(e?.message)ElMessage.error(e.message)}}
function switchTab(value:string|number){if(value==='preview'){sample.value={...initialValues(draft.value!.definition),...sample.value};answers.value={}}}
function addRule(){if(!ruleExam.value||!draft.value)return;draft.value.definition.examRules[ruleExam.value]=Object.fromEntries(allFields.value.filter(isAnswer).map(f=>[f.id,{maxScore:f.maxScore,scoring:f.scoring,partialScore:f.partialScore}]))}
const isList=computed(()=>!draft.value)
defineExpose({load,open,isList})
onMounted(load)
</script>
<template>
<section class="qt-page" v-loading="loading">
  <el-alert v-if="error" :title="error" type="error" :closable="false"/>
  <template v-if="!draft">
    <div class="qt-overview"><div><span class="qt-kicker">共用模板库</span><h2>把题目结构，变成可复用的模板</h2><p>配置组件与作答规则，适用于不同考试的题目录入、练习和导入导出。</p></div><div class="qt-total"><b>{{records.length}}</b><span>个题型模板</span></div></div>
    <div class="qt-toolbar"><el-input v-model="search" clearable placeholder="搜索题型名称" aria-label="搜索题型名称"><template #prefix><Search :size="16"/></template></el-input><el-select v-model="status" aria-label="题型状态"><el-option label="全部状态" value="all"/><el-option label="已启用" value="enabled"/><el-option label="已停用" value="disabled"/></el-select><span>{{filtered.length}} 个题型</span></div>
    <div class="qt-grid"><article v-for="t in filtered" :key="t.id" class="qt-card" :class="{disabled:!t.enabled}"><div class="qt-card-top"><span class="qt-icon" :class="t.id"><component :is="icons[(t.definition.fields[0]?.kind)||'group']" :size="24"/></span><el-tag :type="t.enabled?'success':'info'" effect="light">{{t.enabled?'已启用':'已停用'}}</el-tag></div><button class="qt-title" @click="open(t)">{{t.name}}</button><p>{{t.description||'自定义题目结构，灵活配置组件与规则'}}</p><div class="qt-card-meta"><span>{{t.builtin?'系统预置':'自定义'}} · v{{t.version}}</span><span>{{flattenFields(t.definition.fields).filter(isAnswer).length}} 个作答组件</span></div><div class="qt-card-foot"><span>已用于 <b>{{t.question_count||0}}</b> 道题</span><div><el-tooltip content="编辑题型"><el-button link type="primary" :aria-label="'编辑'+t.name" @click="open(t)"><Pencil :size="17"/></el-button></el-tooltip><el-tooltip content="复制题型"><el-button link :aria-label="'复制'+t.name" @click="open(t,true)"><Copy :size="17"/></el-button></el-tooltip><el-tooltip :content="t.enabled?'停用':'启用'"><el-button link :type="t.enabled?'danger':'success'" :aria-label="(t.enabled?'停用':'启用')+t.name" @click="toggle(t)"><Power :size="17"/></el-button></el-tooltip></div></div></article></div>
    <div class="qt-note"><Layers3 :size="18"/><span>组合题可配置公共材料、共用选项与小题组；同一模板可跨考试复用，题目仍归属各自考试。</span></div>
  </template>
  <template v-else>
    <div class="qt-editor-head"><el-button aria-label="返回题型列表" @click="back"><ArrowLeft :size="17"/>返回</el-button><div><h2>{{draft.name||'新建题型'}}</h2><span>{{(draft as any).isNew?'设计你的题目录入结构':'当前 v'+draft.version+' · 保存为新版本，不改变已有题目'}}</span></div><el-button type="primary" :loading="saving" @click="save"><Check :size="17"/>保存题型</el-button></div>
    <el-alert v-if="saveError" :title="saveError" type="error" :closable="false"/>
    <el-tabs v-model="tab" @tab-change="switchTab" class="qt-tabs"><el-tab-pane label="结构设计" name="design"/><el-tab-pane label="考试评分配置" name="rules"/><el-tab-pane label="录入与答题预览" name="preview"/></el-tabs>
    <div v-if="tab==='design'" class="qt-builder">
      <aside class="qt-palette"><h3>添加组件</h3><p>点击添加，选中小题组后可向组内添加。</p><button v-for="kind in componentKinds" :key="kind" @click="add(kind)"><component :is="icons[kind]" :size="19"/><span><b>{{fieldNames[kind]}}</b><small>{{descriptions[kind]}}</small></span><Plus :size="15"/></button><div class="qt-palette-tip">题目ID、考试、知识点关联和等级为固定基础信息，无需重复添加。</div></aside>
      <main class="qt-canvas"><div class="qt-canvas-heading"><span>表单结构</span><small>{{allFields.length}} 个组件</small></div><el-form label-position="top" class="qt-basics"><el-form-item label="题型名称" required><el-input v-model="draft.name" maxlength="80" placeholder="例如：材料分析题"/></el-form-item><el-form-item label="题型说明"><el-input v-model="draft.description" maxlength="500" placeholder="简要说明用途与作答方式"/></el-form-item></el-form>
        <div v-for="({f,list,depth},i) in entries" :key="f.id" class="qt-block" :class="{active:selected===f.id,'is-group':f.kind==='group'}" :style="{'margin-left':depth*18+'px'}" @click="selected=f.id"><div class="qt-block-head"><button class="qt-block-select" :aria-label="'配置'+f.label" @click="selected=f.id"><GripVertical :size="16"/><span>{{String(i+1).padStart(2,'0')}}</span><b>{{f.label}}</b><em v-if="f.required">必填</em></button><div class="qt-block-actions"><el-button link :disabled="list.indexOf(f)===0" aria-label="上移组件" @click.stop="move(f,list,-1)"><ArrowUp :size="15"/></el-button><el-button link :disabled="list.indexOf(f)===list.length-1" aria-label="下移组件" @click.stop="move(f,list,1)"><ArrowDown :size="15"/></el-button><el-button link type="danger" aria-label="删除组件" @click.stop="remove(f,list)"><Trash2 :size="15"/></el-button></div></div><p>{{f.help||descriptions[f.kind]}}</p><div v-if="f.kind==='group'" class="qt-placeholder">{{f.children.length?'包含 '+f.children.length+' 个组件':'选中此组，然后从左侧添加小题'}}</div><div v-else-if="['single','multiple','boolean'].includes(f.kind)" class="qt-mini-options"><span><i :class="{square:f.kind==='multiple'}"/>{{f.kind==='boolean'?'正确':'选项 A'}}</span><span><i :class="{square:f.kind==='multiple'}"/>{{f.kind==='boolean'?'错误':'选项 B'}}</span></div><div v-else class="qt-placeholder">{{f.defaultValue||'录入时填写'+f.label}}</div><div class="qt-block-caption">{{fieldNames[f.kind]}}<span v-if="isAnswer(f)"> · {{f.maxScore}}分 · {{f.kind==='text'?(f.aiGrading?'AI 判分':'自评练习'):f.scoring==='partial'?'漏选部分得分':'全部正确得分'}}</span></div></div>
        <button class="qt-add-bottom" @click="add('group')"><Plus :size="16"/>添加小题组</button>
      </main>
      <aside class="qt-properties"><h3><Settings2 :size="17"/>组件属性</h3><el-form v-if="active" label-position="top"><div class="qt-property-kind">{{fieldNames[active.kind]}}</div><el-form-item label="组件名称"><el-input v-model="active.label" maxlength="80"/></el-form-item><el-form-item label="填写说明"><el-input v-model="active.help" type="textarea" :rows="2" maxlength="500"/></el-form-item><el-form-item v-if="active.kind!=='group'&&active.kind!=='options'" label="默认内容"><el-input v-model="active.defaultValue" type="textarea" :rows="2"/></el-form-item><div v-if="active.kind!=='group'" class="qt-switch-row"><span>录入时必填</span><el-switch v-model="active.required" aria-label="录入时必填"/></div><template v-if="isAnswer(active)"><div class="qt-switch-row"><span>学生必须作答</span><el-switch v-model="active.answerRequired" aria-label="学生必须作答"/></div><el-form-item label="默认分值"><el-input-number v-model="active.maxScore" :min="0.01" :max="10000" :precision="2"/></el-form-item><el-form-item v-if="active.kind==='multiple'" label="评分方式"><el-select v-model="active.scoring"><el-option label="全部正确才得分" value="exact"/><el-option label="漏选部分得分，错选零分" value="partial"/></el-select></el-form-item><el-form-item v-if="active.scoring==='partial'" label="漏选时每个正确选项得分"><el-input-number v-model="active.partialScore" :min="0.01" :max="10000" :precision="2"/></el-form-item><el-form-item v-if="['single','multiple'].includes(active.kind)" label="选项来源"><el-select v-model="active.optionsSource" placeholder="本小题独立选项"><el-option label="本小题独立选项" value=""/><el-option v-for="f in allFields.filter(f=>f.kind==='options')" :key="f.id" :label="f.label" :value="f.id"/></el-select></el-form-item></template><template v-if="['single','multiple','options'].includes(active.kind)"><el-form-item label="最少选项数"><el-input-number v-model="active.minOptions" :min="2" :max="26"/></el-form-item><el-form-item label="最多选项数"><el-input-number v-model="active.maxOptions" :min="active.minOptions" :max="26"/></el-form-item></template><div v-if="active.kind==='text'" class="qt-grading-option"><div class="qt-switch-row"><span>AI 判分</span><el-switch :model-value="active.aiGrading===true" @change="active.aiGrading=!!$event" aria-label="AI 判分"/></div><b>{{active.aiGrading?'由 AI 评分并给出点评':'提交后对照答案，自行评分'}}</b><p>{{active.aiGrading?'录题时必须填写参考答案、评分要点和满分。判分失败保留作答，可重试。':'展示参考答案与评分要点，学生可填写自评分。自评分单独标记，不计为客观正确率。'}}</p><a v-if="active.aiGrading" href="#ai">配置主观题判分服务 →</a></div></el-form><el-empty v-else description="选择一个组件进行配置" :image-size="60"/></aside>
    </div>
    <section v-else-if="tab==='rules'" class="qt-rules"><h3>同一题型，不同考试评分</h3><p>未配置的考试使用组件默认规则。规则随题型版本保存，已有题目保留录入时的规则。</p><div class="qt-rule-add"><el-select v-model="ruleExam" placeholder="选择考试" filterable><el-option v-for="e in props.exams" :key="e.id" :label="e.name" :value="e.id"/></el-select><el-button :disabled="!ruleExam||!!draft.definition.examRules[ruleExam]" @click="addRule"><Plus :size="16"/>添加考试规则</el-button></div><article v-for="(rules,examId) in draft.definition.examRules" :key="examId" class="qt-rule-card"><header><b>{{exams.find(e=>e.id===examId)?.name||examId}}</b><el-button link type="danger" @click="delete draft.definition.examRules[examId]">恢复默认</el-button></header><div v-for="f in allFields.filter(f=>isAnswer(f)&&rules[f.id])" :key="f.id" class="qt-rule-row"><span>{{f.label}}</span><el-form-item label="分值"><el-input-number v-model="rules[f.id].maxScore" :min="0.01" :precision="2"/></el-form-item><el-select v-if="f.kind==='multiple'" v-model="rules[f.id].scoring" aria-label="考试评分方式"><el-option label="全对得分" value="exact"/><el-option label="漏选部分得分" value="partial"/></el-select><el-form-item v-if="rules[f.id].scoring==='partial'" label="每项得分"><el-input-number v-model="rules[f.id].partialScore" :min="0.01" :precision="2"/></el-form-item><span v-if="f.kind==='text'" class="qt-muted">{{f.aiGrading?'AI 判分':'自评练习'}}</span></div></article><el-empty v-if="!Object.keys(draft.definition.examRules).length" description="所有考试使用组件默认评分规则" :image-size="90"/></section>
    <section v-else class="qt-preview"><div class="qt-preview-tools"><div><h3>先试录，再试答</h3><p>预览内容仅在本次编辑中使用，不会创建题目。</p></div><el-radio-group v-model="previewMode"><el-radio-button value="author">录入预览</el-radio-button><el-radio-button value="mobile"><Smartphone :size="14"/>答题预览</el-radio-button></el-radio-group></div><el-form v-if="previewMode==='author'" label-position="top" class="qt-author-preview"><QuestionFields :fields="draft.definition.fields" :values="sample"/></el-form><div v-else class="qt-phone"><div class="qt-phone-top"><span>9:41</span><span class="qt-phone-speaker"/><span>•••</span></div><div class="qt-phone-heading">{{draft.name||'题目预览'}}</div><QuestionPreview :fields="draft.definition.fields" :values="sample" :answers="answers"/><p class="qt-muted">预览模式 · 作答不会提交</p></div></section>
  </template>
</section>
</template>
<style scoped>
.qt-grading-option{padding:14px;background:var(--qt-soft);border:1px solid var(--el-color-primary-light-7);border-radius:8px;margin-top:20px}.qt-grading-option .qt-switch-row{margin:0 0 8px}.qt-grading-option b{font-size:12px;font-weight:600}.qt-grading-option p{color:var(--muted);font-size:12px;line-height:1.8;margin-top:8px}.qt-grading-option a{display:block;color:var(--primary);font-size:12px;margin-top:12px}

